// src/pages/Section2.js
import React from 'react';
import './Pre.css';
import { Link } from 'react-router-dom';

function Section2() {
  const triggerPattern = (patternNumber) => {
    console.log('Triggering pattern:', patternNumber);
    // TODO: Connect this with Arduino functionality
  };

  return (
    <>
      <header>
        <div className="logo">
          <h1>SonicGLow<br />Cube</h1>
        </div>
       <nav>
                         <ul>
                           <li><Link to="/">Home</Link></li>
                           <li><Link to="/resources">Resources</Link></li>
                           <li><Link to="/cube">SonicGlow Cube</Link></li>
                           <li><Link to="/about" className="active">About Us</Link></li>
                         </ul>
                       </nav>
      </header>

      <main>
        <div className="pattern-grid">
          {[...Array(10)].map((_, index) => (
            <button
              key={index}
              className="pattern-box"
              onClick={() => triggerPattern(index + 1)}
            >
              <span>Pattern {String(index + 1).padStart(2, '0')}</span>
            </button>
          ))}
        </div>
      </main>
    </>
  );
}

export default Section2;
